      --color-surface: #1e1e1e;
      --color-text: #e0e0e0;
      --color-text-muted: #a0a0a0;
      --color-border: #333333;
      --color-focus: #5c94e3;
      --color-hover: #2c2c2c;
    }

    body {
      background-color: var(--color-bg);
      color: var(--color-text);
      font-family: system-ui, -apple-system, sans-serif;
      line-height: 1.6;
      margin: 0;
      padding: 2rem;
      display: flex;
      justify-content: center;
    }

    .skip-link {
      position: absolute;
      top: -100px;
      left: 1rem;
      background: var(--color-focus);
      color: #000;
      padding: 0.5rem 1rem;
      text-decoration: none;
      border-radius: 4px;
      font-weight: bold;
    }

    .skip-link:focus-visible {
      top: 1rem;
      outline: 2px solid #fff;
      outline-offset: 2px;
    }

    main {
      width: 100%;
      max-width: 600px;
    }

    main:focus-visible {
      outline: none;
    }

    h1 {
      font-size: 2.5rem;
      margin-bottom: 2rem;
      color: #ffffff;
    }

    .example {
      background-color: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: 8px;
      margin-bottom: 1rem;
      overflow: hidden;
    }

    .example h2 {
      margin: 0;
    }

    .faq-trigger {
      width: 100%;
      text-align: left;
      background: none;
      border: none;
      padding: 1.25rem;
      color: var(--color-text);
      font-size: 1.125rem;
      font-weight: 500;
      font-family: inherit;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      transition: background-color 0.2s;
    }

    .faq-trigger:hover {
      background-color: var(--color-hover);
    }

    .faq-trigger:focus-visible {
      outline: 2px solid transparent;
      box-shadow: inset 0 0 0 3px var(--color-focus);
    }

    @media (forced-colors: active) {
      .faq-trigger:focus-visible {
        outline: 2px solid ButtonText;
        outline-offset: -4px;
      }
      .faq-trigger {
        border-bottom: 1px solid ButtonBorder;
      }
    }

    .chevron {
      width: 1.5rem;
      height: 1.5rem;
      fill: currentColor;
      transition: transform 0.2s;
    }

    .chevron.open {
      transform: rotate(180deg);
    }

    .details {
      padding: 0 1.25rem 1.25rem 1.25rem;
      color: var(--color-text-muted);
    }

    .details[hidden] {
      display: none;
    }

    .details p {
      margin: 0;
      margin-top: 0.5rem;
    }
  </style>
  <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
  <script src="https://unpkg.com/babel-standalone@6/babel.min.js"></script>
</head>
<body>
  <div id="root"></div>
  <script type="text/babel">
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats purr for many reasons — contentment, self-soothing, and healing. The frequency of a cat's purr has been shown to promote tissue regeneration and bone healing."
      },
      {
        question: "Why do cats knead?",
        answer: "Kneading is a behavior leftover from kittenhood, when they knead their mother to stimulate milk flow. In adult cats, it often expresses comfort, happiness, or marks their territory with scent glands in their paws."
      },
      {
        question: "Can cats see in the dark?",
        answer: "Cats have excellent night vision. Their eyes possess a reflective layer called the tapetum lucidum, allowing them to see in light levels six times lower than what a human needs."
      },
      {
        question: "Why do cats sleep so much?",
        answer: "Cats are crepuscular predators, meaning they are most active at dawn and dusk. Sleeping 12-16 hours a day helps them conserve energy for hunting (or playing)."
      }
    ];

    function FAQItem({ question, answer }) {
      const [isOpen, setIsOpen] = React.useState(false);

      return (
        <div className="example">
          <h2>
            <button 
              type="button" 
              aria-expanded={isOpen} 
              onClick={() => setIsOpen(!isOpen)}
              className="faq-trigger"
            >
              {question}
              <svg 
                className={`chevron ${isOpen ? 'open' : ''}`} 
                aria-hidden="true" 
                viewBox="0 0 24 24"
              >
                <path d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z" />
              </svg>
            </button>
          </h2>
          <div className="details" hidden={!isOpen}>
            <p>{answer}</p>
          </div>
        </div>
      );
    }

    function App() {
      return (
        <React.Fragment>
          <a href="#maincontent" className="skip-link">Skip to main content</a>
          <main id="maincontent" tabIndex="-1">
            <h1>Cat FAQ</h1>
            {faqs.map((faq, i) => (
              <FAQItem key={i} question={faq.question} answer={faq.answer} />
            ))}
          </main>
        </React.Fragment>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
